begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','replace_gi_location_reference',array['uuid','text','text','jsonb'],'GI reference replacement is an audited RPC');
select ok(not has_table_privilege('service_role','public.version_comparisons','UPDATE'),'No unused direct comparison UPDATE grant');
select ok(not has_table_privilege('service_role','public.version_comparisons','DELETE'),'No unused direct comparison DELETE grant');
select ok(not has_table_privilege('service_role','public.gi_location_references','INSERT'),'GI direct inserts denied');
select ok(not has_table_privilege('service_role','public.gi_location_references','UPDATE'),'GI direct updates denied');
select ok(not has_table_privilege('service_role','public.gi_location_references','DELETE'),'GI direct deletes denied');
select ok(not has_function_privilege('authenticated','public.replace_gi_location_reference(uuid,text,text,jsonb)','EXECUTE'),'Authenticated cannot replace master');
select ok(not has_function_privilege('anon','public.replace_gi_location_reference(uuid,text,text,jsonb)','EXECUTE'),'Anonymous cannot replace master');
create function pg_temp.uid(n integer) returns uuid language sql immutable as $$select ('a5190000-0001-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.uid(1),'gi.admin.synthetic@pln.co.id'),(pg_temp.uid(2),'gi.reviewer.synthetic@pln.co.id'),(pg_temp.uid(3),'gi.operator.synthetic@pln.co.id');
update public.profiles set status='ACTIVE' where id in(pg_temp.uid(1),pg_temp.uid(2),pg_temp.uid(3));
insert into public.user_role_assignments(user_id,role) values(pg_temp.uid(1),'RST_ADMIN'),(pg_temp.uid(2),'RST_REVIEWER'),(pg_temp.uid(3),'UNIT_OPERATOR');
insert into public.unit_induk(id,code,name) values(pg_temp.uid(4),'GI SYNTHETIC','Synthetic coordinate unit');
create function pg_temp.gi(lat numeric default 0) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('unit_induk_key','GI SYNTHETIC','upt','UPT SYNTHETIC','nama_gi','GI SYNTHETIC','latitude',lat,'longitude',0))$$;
create function pg_temp.replace(actor_n integer default 1,version text default 'synthetic-gi-v1',hash text default repeat('a',64),rows jsonb default pg_temp.gi()) returns jsonb language sql as $$select public.replace_gi_location_reference(pg_temp.uid(actor_n),version,hash,rows)$$;
select throws_ok($$select pg_temp.replace(2)$$,'42501',null,'Reviewer cannot replace coordinate reference');
select throws_ok($$select pg_temp.replace(3)$$,'42501',null,'Operator cannot replace coordinate reference');
select throws_ok($$select pg_temp.replace(1,' ',repeat('a',64))$$,'22023',null,'Blank version rejected');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1','bad')$$,'22023',null,'Invalid source hash rejected');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('a',64),'[]')$$,'22023',null,'Empty reference rejected');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('a',64),pg_temp.gi(91))$$,'22023',null,'Coordinate bounds rechecked server-side');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('a',64),pg_temp.gi()||pg_temp.gi(1))$$,'22023',null,'Normalized duplicate keys rejected server-side');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('a',64),jsonb_set(pg_temp.gi(),'{0,unit_induk_key}','"UNKNOWN"'))$$,'22023',null,'Unknown unit rejected without deleting master');
select lives_ok($$select pg_temp.replace()$$,'Explicit RST admin imports reference');
select is((select count(*) from public.gi_location_references where source_version='synthetic-gi-v1'),1::bigint,'One normalized row persisted');
select is((select latitude from public.gi_location_references where source_version='synthetic-gi-v1'),0::double precision,'Zero coordinate retained');
select is((select count(*) from public.audit_events where actor_id=pg_temp.uid(1) and action='GI_REFERENCE_REPLACED'),1::bigint,'Audit appended once');
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v2')$$,'22023',null,'Cannot overwrite another reference version implicitly');
select is((select source_hash from public.gi_location_references where source_version='synthetic-gi-v1'),repeat('a',64),'Conflicting version leaves original untouched');
create function pg_temp.fail_gi_audit() returns trigger language plpgsql as $$begin if new.action='GI_REFERENCE_REPLACED' and new.actor_id=pg_temp.uid(1) then raise exception 'Synthetic GI audit outage'; end if; return new; end$$;
create trigger synthetic_gi_audit before insert on public.audit_events for each row execute function pg_temp.fail_gi_audit();
select throws_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('b',64),pg_temp.gi(1))$$,'P0001',null,'Audit failure rolls back reference replacement');
select is((select latitude from public.gi_location_references where source_version='synthetic-gi-v1'),0::double precision,'Original coordinates restored on audit failure');
drop trigger synthetic_gi_audit on public.audit_events;
select lives_ok($$select pg_temp.replace(1,'synthetic-gi-v1',repeat('b',64),pg_temp.gi(1))$$,'Same-version replacement is atomic');
select is((select count(*) from public.gi_location_references where source_version='synthetic-gi-v1'),1::bigint,'Replacement does not append duplicates');
select is((select count(*) from public.audit_events where actor_id=pg_temp.uid(1) and action='GI_REFERENCE_REPLACED'),2::bigint,'Replacement has second audit');
select ok(not exists(select 1 from public.audit_events where actor_id=pg_temp.uid(1) and details::text like '%UPT SYNTHETIC%'),'Audit holds aggregate metadata, never row labels');
select * from finish();
rollback;
